#import "ResearchCatalog.h"
#include <assert.h>
int main(void){@autoreleasepool{NSMutableSet *keys=[NSMutableSet new];for(NSString *page in @[@"model",@"library",@"diagnostics"]){NSArray *sections=TIOResearchSections(page);assert(sections.count);for(NSDictionary *s in sections)for(NSDictionary *r in s[@"rows"]){assert(![keys containsObject:r[@"key"]]);[keys addObject:r[@"key"]];assert([r[@"title"] length]&&[r[@"icon"] length]);}}assert(keys.count==32);assert([keys containsObject:@"tts"]);assert([keys containsObject:@"ttsEngine"]);assert([keys containsObject:@"ttsKey"]);assert([keys containsObject:@"ttsTest"]);assert([keys containsObject:@"experimentalOTA"]);assert([keys containsObject:@"subtitleHUD"]);assert([keys containsObject:@"navigation"]);assert([keys containsObject:@"a2ui"]);assert([keys containsObject:@"knowledge"]);assert([TIOResearchSections(@"model")[0][@"rows"][0][@"key"] isEqual:@"agent"]);assert([keys containsObject:@"lifelogAudio"]);assert([keys containsObject:@"capture"]);assert([keys containsObject:@"todoTest"]);assert(!TIOResearchSections(@"unknown").count);NSLog(@"PASS: research routes unique and TTS controls reachable");}return 0;}
